/** Static markup for one New Year variant with the celebrated year filled in (digits only). */
export function newYearMarkup(mode: SceneMode, year: number): string {
  const digits = String(Math.trunc(Math.abs(year))).replace(/[^0-9]/g, "").slice(0, 4) || "";
  return NY_SCENES[mode].replaceAll("{{YEAR}}", digits);
}

